-- Plan 0.3b: an income generated by a recurring series records which one,
-- like expenses.recurring_expense_id (000012). It makes generation
-- idempotent (a retried run finds the income instead of booking it twice)
-- and lets the app tell fixed incomes from manual ones.
-- Incomes generated before this migration stay unlinked (NULL): there is
-- no reliable way to match them to their series.
ALTER TABLE incomes
    ADD COLUMN recurring_income_id UUID REFERENCES recurring_incomes(id) ON DELETE SET NULL;

CREATE INDEX idx_incomes_recurring ON incomes(recurring_income_id) WHERE recurring_income_id IS NOT NULL;
